export default function Icon({ name, className = "", ...rest }) {
  const filled = F[name];
  if (filled) {
    const [viewBox, paths] = filled;
    return (
      <svg className={`ic ic-fill ${className}`} viewBox={viewBox} aria-hidden="true" focusable="false" {...rest}>
        {paths.map((d) => (
          <path key={d.slice(0, 12)} d={d} />
        ))}
      </svg>
    );
  }
  return (
    <svg className={`ic ${className}`} viewBox="0 0 24 24" aria-hidden="true" focusable="false" {...rest}>
      {S[name]}
    </svg>
  );
}
